#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RelationalSqlGpuBridgeReport {
    pub query_count: usize,
    pub gpu_executed_count: usize,
    pub cpu_fallback_count: usize,
    pub gpu_executed_permyriad: u16,
    pub cpu_fallback_permyriad: u16,
}

impl RelationalSqlGpuBridgeReport {
    pub fn from_results(results: &[RelationalSelectResult]) -> Self {
        let query_count = results.len();
        let gpu_executed_count = results
            .iter()
            .filter(|result| matches!(result.executed_target, DeviceTarget::Gpu(_)))
            .count();
        let cpu_fallback_count = results
            .iter()
            .filter(|result| result.fallback_reason.is_some())
            .count();

        Self {
            query_count,
            gpu_executed_count,
            cpu_fallback_count,
            gpu_executed_permyriad: permyriad(gpu_executed_count, query_count),
            cpu_fallback_permyriad: permyriad(cpu_fallback_count, query_count),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BoundRelationalSelect {
    selected_columns: Vec<RelationalColumn>,
    selected_indexes: Vec<usize>,
    group_by_index: Option<usize>,
    filter: Option<(usize, SelectFilterOp, SqlValue)>,
    filters: Vec<(usize, SelectFilterOp, SqlValue)>,
    filter_groups: Vec<Vec<(usize, SelectFilterOp, SqlValue)>>,
    order: Option<(usize, bool)>,
}

fn resident_route_query_shape(
    select: &Select,
    table: &RelationalTable,
    bound: &BoundRelationalSelect,
) -> Option<String> {
    if select.distinct {
        return resident_route_distinct_projection_shape(select, table, bound);
    }

    match &select.projection {
        SelectProjection::GroupedCount { column } => {
            return resident_route_grouped_aggregate_shape(select, table, bound, column, column);
        }
        SelectProjection::GroupedSum {
            group_column,
            sum_column,
        } => {
            return resident_route_grouped_aggregate_shape(
                select,
                table,
                bound,
                group_column,
                sum_column,
            );
        }
        SelectProjection::GroupedAvg {
            group_column,
            avg_column,
        } => {
            return resident_route_grouped_aggregate_shape(
                select,
                table,
                bound,
                group_column,
                avg_column,
            );
        }
        SelectProjection::GroupedMin {
            group_column,
            min_column,
        } => {
            return resident_route_grouped_aggregate_shape(
                select,
                table,
                bound,
                group_column,
                min_column,
            );
        }
        SelectProjection::GroupedMax {
            group_column,
            max_column,
        } => {
            return resident_route_grouped_aggregate_shape(
                select,
                table,
                bound,
                group_column,
                max_column,
            );
        }
        _ => {}
    }

    if select.order_by.is_some() {
        return resident_route_ordered_projection_shape(select, table, bound);
    }

    if select.offset.is_some() {
        return None;
    }
    if select.group_by.is_some() || !select.having_groups.is_empty() {
        return None;
    }

    match &select.projection {
        SelectProjection::CountAll => resident_route_count_shape(table, bound),
        SelectProjection::Sum { column }
        | SelectProjection::Avg { column }
        | SelectProjection::Min { column }
        | SelectProjection::Max { column } => {
            let idx = table
                .columns
                .iter()
                .position(|candidate| candidate.name == *column)?;
            if table.columns[idx].ty != SqlType::Int4 || select.limit.is_some() {
                return None;
            }
            if bound.filter.is_none() && bound.filters.is_empty() && bound.filter_groups.is_empty()
            {
                return Some("int4_scalar_aggregate".to_string());
            }
            let filter_groups = if !bound.filter_groups.is_empty() {
                bound.filter_groups.clone()
            } else if !bound.filters.is_empty() {
                vec![bound.filters.clone()]
            } else {
                vec![vec![bound.filter.clone()?]]
            };
            if filter_groups.len() == 1 && filter_groups[0].len() == 1 {
                let (filter_idx, op, value) = filter_groups[0][0].clone();
                return (filter_idx == idx
                    && resident_device_i32_comparison(op).is_some()
                    && matches!(value, SqlValue::Int4(_)))
                .then(|| "int4_filtered_scalar_aggregate".to_string());
            }
            if filter_groups.len() == 1 && filter_groups[0].len() == 2 {
                let mut lower = false;
                let mut upper = false;
                for (filter_idx, op, value) in &filter_groups[0] {
                    if *filter_idx != idx || !matches!(value, SqlValue::Int4(_)) {
                        return None;
                    }
                    match op {
                        SelectFilterOp::Gte => lower = true,
                        SelectFilterOp::Lte => upper = true,
                        _ => return None,
                    }
                }
                return (lower && upper).then(|| "int4_between_scalar_aggregate".to_string());
            }
            None
        }
        SelectProjection::Columns(columns) if columns.len() == 1 => {
            let idx = table
                .columns
                .iter()
                .position(|candidate| candidate.name == columns[0])?;
            let filter_groups = if !bound.filter_groups.is_empty() {
                bound.filter_groups.clone()
            } else if !bound.filters.is_empty() {
                vec![bound.filters.clone()]
            } else {
                vec![vec![bound.filter.clone()?]]
            };
            let (filter_idx, op, value) = filter_groups.first()?.first()?.clone();
            (table.columns[idx].ty == SqlType::Int4
                && idx == filter_idx
                && resident_device_i32_comparison(op).is_some()
                && matches!(value, SqlValue::Int4(_))
                && filter_groups.len() == 1
                && filter_groups[0].len() == 1)
                .then(|| "int4_projection".to_string())
        }
        _ => None,
    }
}

fn resident_route_ordered_projection_shape(
    select: &Select,
    table: &RelationalTable,
    bound: &BoundRelationalSelect,
) -> Option<String> {
    if select.group_by.is_some()
        || !select.having_groups.is_empty()
        || bound.selected_indexes.len() != 1
        || select.limit.is_none()
        || bound.filter_groups.len() != 1
        || bound.filter_groups[0].len() != 1
    {
        return None;
    }
    let projection_idx = bound.selected_indexes[0];
    if table.columns[projection_idx].ty != SqlType::Int4 {
        return None;
    }
    let (order_idx, _) = bound.order?;
    if order_idx != projection_idx {
        return None;
    }
    let (filter_idx, op, value) = bound.filter_groups[0][0].clone();
    (filter_idx == projection_idx
        && resident_device_i32_comparison(op).is_some()
        && matches!(value, SqlValue::Int4(_)))
    .then(|| "int4_ordered_projection".to_string())
}

fn resident_route_distinct_projection_shape(
    select: &Select,
    table: &RelationalTable,
    bound: &BoundRelationalSelect,
) -> Option<String> {
    if select.group_by.is_some()
        || !select.having_groups.is_empty()
        || bound.selected_indexes.len() != 1
    {
        return None;
    }
    let SelectProjection::Columns(_columns) = &select.projection else {
        return None;
    };
    if select.offset.is_some() && (bound.order.is_none() || select.limit.is_none()) {
        return None;
    }
    let projection_idx = bound.selected_indexes[0];
    if table.columns[projection_idx].ty != SqlType::Int4 {
        return None;
    }
    if let Some((order_idx, _descending)) = bound.order {
        if order_idx != projection_idx {
            return None;
        }
    }
    if bound.filter.is_none() && bound.filters.is_empty() && bound.filter_groups.is_empty() {
        return Some("int4_distinct_projection".to_string());
    }
    let filter_groups = if !bound.filter_groups.is_empty() {
        bound.filter_groups.clone()
    } else if !bound.filters.is_empty() {
        vec![bound.filters.clone()]
    } else {
        vec![vec![bound.filter.clone()?]]
    };
    if filter_groups.len() != 1 || filter_groups[0].len() != 1 {
        return None;
    }
    let (filter_idx, op, value) = filter_groups[0][0].clone();
    (filter_idx == projection_idx
        && resident_device_i32_comparison(op).is_some()
        && matches!(value, SqlValue::Int4(_)))
    .then(|| "int4_filtered_distinct_projection".to_string())
}

fn resident_route_grouped_aggregate_shape(
    select: &Select,
    table: &RelationalTable,
    bound: &BoundRelationalSelect,
    group_column: &str,
    value_column: &str,
) -> Option<String> {
    if select.offset.is_some() {
        return None;
    }
    let group_by = select.group_by.as_ref()?;
    if !group_by.eq_ignore_ascii_case(group_column) {
        return None;
    }
    let group_idx = table
        .columns
        .iter()
        .position(|candidate| candidate.name == group_column)?;
    let value_idx = table
        .columns
        .iter()
        .position(|candidate| candidate.name == value_column)?;
    if table.columns[group_idx].ty != SqlType::Int4 || table.columns[value_idx].ty != SqlType::Int4
    {
        return None;
    }
    if bound.filter.is_none() && bound.filters.is_empty() && bound.filter_groups.is_empty() {
        return Some("int4_grouped_aggregate".to_string());
    }
    let filter_groups = if !bound.filter_groups.is_empty() {
        bound.filter_groups.clone()
    } else if !bound.filters.is_empty() {
        vec![bound.filters.clone()]
    } else {
        vec![vec![bound.filter.clone()?]]
    };
    if filter_groups.len() != 1 || filter_groups[0].len() != 1 {
        return None;
    }
    let (filter_idx, op, value) = filter_groups[0][0].clone();
    (table.columns.get(filter_idx)?.ty == SqlType::Int4
        && resident_device_i32_comparison(op).is_some()
        && matches!(value, SqlValue::Int4(_)))
    .then(|| "int4_filtered_grouped_aggregate".to_string())
}

fn resident_route_count_shape(
    table: &RelationalTable,
    bound: &BoundRelationalSelect,
) -> Option<String> {
    if bound.filter.is_none() && bound.filters.is_empty() && bound.filter_groups.is_empty() {
        return Some("count_all".to_string());
    }
    let filter_groups = if !bound.filter_groups.is_empty() {
        bound.filter_groups.clone()
    } else if !bound.filters.is_empty() {
        vec![bound.filters.clone()]
    } else {
        vec![vec![bound.filter.clone()?]]
    };
    if filter_groups.is_empty() {
        return Some("count_all".to_string());
    }
    if filter_groups.len() == 1 && filter_groups[0].len() == 1 {
        let (idx, op, value) = &filter_groups[0][0];
        let column = table.columns.get(*idx)?;
        return match (column.ty, op, value) {
            (SqlType::Int4, SelectFilterOp::Eq, SqlValue::Int4(_)) => {
                Some("int4_equality_count".to_string())
            }
            (
                SqlType::Int4,
                SelectFilterOp::Lt | SelectFilterOp::Lte | SelectFilterOp::Gt | SelectFilterOp::Gte,
                SqlValue::Int4(_),
            ) => Some("int4_range_count".to_string()),
            (SqlType::Text, SelectFilterOp::LikePrefix, SqlValue::Text(_)) => {
                Some("text_prefix_like_count".to_string())
            }
            _ => None,
        };
    }
    filter_groups
        .iter()
        .flatten()
        .all(|(idx, _op, value)| {
            table.columns.get(*idx).is_some_and(|column| {
                column.ty == SqlType::Int4 && matches!(value, SqlValue::Int4(_))
            })
        })
        .then(|| "int4_filter_group_count".to_string())
}

fn resident_route_d2h_rows_estimate(select: &Select, resident_row_count: usize) -> usize {
    match select.projection {
        SelectProjection::CountAll
        | SelectProjection::Sum { .. }
        | SelectProjection::Avg { .. }
        | SelectProjection::Min { .. }
        | SelectProjection::Max { .. } => 1,
        SelectProjection::GroupedCount { .. }
        | SelectProjection::GroupedSum { .. }
        | SelectProjection::GroupedAvg { .. }
        | SelectProjection::GroupedMin { .. }
        | SelectProjection::GroupedMax { .. } => select
            .limit
            .unwrap_or(resident_row_count)
            .min(resident_row_count),
        _ => select
            .limit
            .unwrap_or(resident_row_count)
            .min(resident_row_count),
    }
}

fn resident_route_d2h_bytes_estimate(
    select: &Select,
    query_shape: &str,
    snapshot: &RelationalResidencySnapshot,
) -> u64 {
    const COUNT_RESULT_BYTES: u64 = std::mem::size_of::<u64>() as u64;
    const I32_RESULT_BYTES: u64 = std::mem::size_of::<i32>() as u64;
    const RESULT_LEN_BYTES: u64 = std::mem::size_of::<u64>() as u64;
    const GROUPED_STATS_BYTES: u64 = (std::mem::size_of::<i32>()
        + std::mem::size_of::<u64>()
        + std::mem::size_of::<i64>()
        + (2 * std::mem::size_of::<i32>())) as u64;

    let rows = resident_route_d2h_rows_estimate(select, snapshot.row_count);
    let row_bytes = |bytes_per_row: u64| {
        u64::try_from(rows)
            .unwrap_or(u64::MAX)
            .saturating_mul(bytes_per_row)
            .saturating_add(RESULT_LEN_BYTES)
    };
    let resident_row_bytes = |bytes_per_row: u64| {
        u64::try_from(snapshot.row_count)
            .unwrap_or(u64::MAX)
            .saturating_mul(bytes_per_row)
            .saturating_add(RESULT_LEN_BYTES)
    };

    match query_shape {
        "text_prefix_like_count" => snapshot.resident_bytes,
        "int4_grouped_aggregate" | "int4_filtered_grouped_aggregate" => {
            row_bytes(GROUPED_STATS_BYTES)
        }
        "int4_projection" | "int4_ordered_projection" => row_bytes(I32_RESULT_BYTES),
        "int4_distinct_projection" | "int4_filtered_distinct_projection" => {
            resident_row_bytes(I32_RESULT_BYTES)
        }
        "int4_scalar_aggregate"
        | "int4_filtered_scalar_aggregate"
        | "int4_between_scalar_aggregate" => GROUPED_STATS_BYTES.saturating_add(RESULT_LEN_BYTES),
        "count_all" | "int4_equality_count" | "int4_range_count" | "int4_filter_group_count" => {
            COUNT_RESULT_BYTES
        }
        _ => 0,
    }
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct RelationalIndexKey {
    table: String,
    column: String,
    value: String,
}

const PUBLIC_SCHEMA_NAME: &str = "public";
const FIRST_USER_RELATION_OID: u32 = 16_384;
const FIRST_USER_COLUMN_ID: u32 = 1;

impl RelationalColumn {
    fn from_def(
        id: u32,
        table_oid: u32,
        attnum: i16,
        def: ColumnDef,
        type_oid: u32,
        type_size: i16,
    ) -> Self {
        Self {
            id,
            table_oid,
            attnum,
            name: def.name,
            ty: def.ty,
            domain: def.domain,
            default: def.default,
            type_oid,
            type_size,
        }
    }

    pub fn as_column_def(&self) -> ColumnDef {
        ColumnDef {
            name: self.name.clone(),
            ty: self.ty,
            domain: self.domain.clone(),
            default: self.default.clone(),
        }
    }
}

fn sql_value_matches_type(value: &SqlValue, ty: SqlType) -> bool {
    matches!(
        (value, ty),
        (SqlValue::Int4(_), SqlType::Int4) | (SqlValue::Text(_), SqlType::Text)
    )
}

fn column_default_matches_type(value: &ColumnDefault, ty: SqlType) -> bool {
    match value {
        ColumnDefault::Literal(value) => sql_value_matches_type(value, ty),
        ColumnDefault::SequenceNextVal { .. } => ty == SqlType::Int4,
    }
}

fn add_column_default_supported(default: &ColumnDefault) -> bool {
    match default {
        ColumnDefault::Literal(_) => true,
        ColumnDefault::SequenceNextVal {
            create_if_missing, ..
        } => !create_if_missing,
    }
}

fn sequence_defaults(columns: &[ColumnDef]) -> impl Iterator<Item = &ColumnDefault> {
    columns.iter().filter_map(|column| column.default.as_ref())
}

fn relational_row_key(table: &str, row_id: u64) -> String {
    format!("rel/{table}/{row_id:020}")
}

fn relational_key_prefix(table: &str) -> String {
    format!("rel/{table}/")
}

fn relational_index_value(value: &SqlValue) -> String {
    match value {
        SqlValue::Int4(value) => format!("i:{value}"),
        SqlValue::Int8(value) => format!("n:{value}"),
        SqlValue::Numeric(value) => format!("d:{value}"),
        SqlValue::Text(value) => format!("t:{value}"),
    }
}

fn relational_resident_value_bytes(value: &SqlValue) -> u64 {
    match value {
        SqlValue::Int4(_) => 4,
        SqlValue::Int8(_) => 8,
        SqlValue::Numeric(value) => value.len() as u64,
        SqlValue::Text(value) => value.len() as u64,
    }
}

fn encode_relational_row(values: &[SqlValue]) -> String {
    values
        .iter()
        .map(|value| match value {
            SqlValue::Int4(value) => format!("i:{value}"),
            SqlValue::Int8(value) => format!("n:{value}"),
            SqlValue::Numeric(value) => format!("d:{value}"),
            SqlValue::Text(value) => {
                format!("t:{}", value.replace('\\', "\\\\").replace('|', "\\|"))
            }
        })
        .collect::<Vec<_>>()
        .join("|")
}

fn decode_relational_row(
    input: &str,
    columns: &[RelationalColumn],
) -> Result<Vec<SqlValue>, ExecuteError> {
    let parts = split_escaped_row(input);
    if parts.len() != columns.len() {
        return Err(ExecuteError::Engine(EngineError::ApplyFailed(
            "stored relational row does not match catalog shape".to_string(),
        )));
    }
    parts
        .into_iter()
        .zip(columns.iter())
        .map(|(part, column)| {
            match (
                part.strip_prefix("i:"),
                part.strip_prefix("t:"),
                part.strip_prefix("n:"),
                column.ty,
            ) {
                (Some(value), _, _, SqlType::Int4) => {
                    value.parse::<i32>().map(SqlValue::Int4).map_err(|_| {
                        ExecuteError::Engine(EngineError::ApplyFailed(
                            "stored INT value is invalid".to_string(),
                        ))
                    })
                }
                (_, Some(value), _, SqlType::Text) => Ok(SqlValue::Text(value.to_string())),
                _ => Err(ExecuteError::Engine(EngineError::ApplyFailed(format!(
                    "stored value for column \"{}\" has wrong type",
                    column.name
                )))),
            }
        })
        .collect()
}

fn split_escaped_row(input: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    let mut escaped = false;
    for ch in input.chars() {
        if escaped {
            current.push(ch);
            escaped = false;
        } else if ch == '\\' {
            escaped = true;
        } else if ch == '|' {
            out.push(current);
            current = String::new();
        } else {
            current.push(ch);
        }
    }
    if escaped {
        current.push('\\');
    }
    out.push(current);
    out
}

fn compare_sql_values(left: &SqlValue, right: &SqlValue) -> Ordering {
    match (left, right) {
        (SqlValue::Int4(left), SqlValue::Int4(right)) => left.cmp(right),
        (SqlValue::Int8(left), SqlValue::Int8(right)) => left.cmp(right),
        (SqlValue::Int4(left), SqlValue::Int8(right)) => i64::from(*left).cmp(right),
        (SqlValue::Int8(left), SqlValue::Int4(right)) => left.cmp(&i64::from(*right)),
        (SqlValue::Numeric(left), SqlValue::Numeric(right)) => compare_numeric_strings(left, right),
        (SqlValue::Text(left), SqlValue::Text(right)) => left.cmp(right),
        (SqlValue::Int4(_) | SqlValue::Int8(_), SqlValue::Numeric(_) | SqlValue::Text(_)) => {
            Ordering::Less
        }
        (SqlValue::Numeric(_), SqlValue::Int4(_) | SqlValue::Int8(_)) => Ordering::Greater,
        (SqlValue::Numeric(_), SqlValue::Text(_)) => Ordering::Less,
        (SqlValue::Text(_), SqlValue::Int4(_) | SqlValue::Int8(_) | SqlValue::Numeric(_)) => {
            Ordering::Greater
        }
    }
}

fn compare_numeric_strings(left: &str, right: &str) -> Ordering {
    let (left_negative, left_abs) = left
        .strip_prefix('-')
        .map_or((false, left), |value| (true, value));
    let (right_negative, right_abs) = right
        .strip_prefix('-')
        .map_or((false, right), |value| (true, value));
    match (left_negative, right_negative) {
        (true, false) => return Ordering::Less,
        (false, true) => return Ordering::Greater,
        _ => {}
    }
    let magnitude = compare_unsigned_numeric_strings(left_abs, right_abs);
    if left_negative {
        magnitude.reverse()
    } else {
        magnitude
    }
}

fn compare_unsigned_numeric_strings(left: &str, right: &str) -> Ordering {
    let (left_whole, left_frac) = left.split_once('.').unwrap_or((left, ""));
    let (right_whole, right_frac) = right.split_once('.').unwrap_or((right, ""));
    let left_whole = left_whole.trim_start_matches('0');
    let right_whole = right_whole.trim_start_matches('0');
    left_whole
        .len()
        .cmp(&right_whole.len())
        .then_with(|| left_whole.cmp(right_whole))
        .then_with(|| {
            let width = left_frac.len().max(right_frac.len());
            let mut left_padded = left_frac.to_string();
            let mut right_padded = right_frac.to_string();
            left_padded.extend(std::iter::repeat_n('0', width - left_padded.len()));
            right_padded.extend(std::iter::repeat_n('0', width - right_padded.len()));
            left_padded.cmp(&right_padded)
        })
}

fn select_filter_matches(left: &SqlValue, op: SelectFilterOp, right: &SqlValue) -> bool {
    match op {
        SelectFilterOp::Eq => left == right,
        SelectFilterOp::Lt => compare_sql_values(left, right).is_lt(),
        SelectFilterOp::Lte => !compare_sql_values(left, right).is_gt(),
        SelectFilterOp::Gt => compare_sql_values(left, right).is_gt(),
        SelectFilterOp::Gte => !compare_sql_values(left, right).is_lt(),
        SelectFilterOp::LikePrefix => match (left, right) {
            (SqlValue::Text(left), SqlValue::Text(prefix)) => left.starts_with(prefix),
            _ => false,
        },
    }
}

fn sort_relational_keys(keyed_rows: &mut [(String, SqlValue)], descending: bool) {
    keyed_rows.sort_by(|(left_key, left_value), (right_key, right_value)| {
        let value_order = compare_sql_values(left_value, right_value);
        let order = if descending {
            value_order.reverse()
        } else {
            value_order
        };
        order.then_with(|| left_key.cmp(right_key))
    });
}

fn relational_column_index(table: &RelationalTable, name: &str) -> Result<usize, ExecuteError> {
    table
        .columns
        .iter()
        .position(|column| column.name == name)
        .ok_or_else(|| {
            ExecuteError::Engine(EngineError::ApplyFailed(format!(
                "column \"{}\" does not exist",
                name
            )))
        })
}

fn bind_relational_select(
    table: &RelationalTable,
    select: &Select,
) -> Result<BoundRelationalSelect, ExecuteError> {
    let selected_indexes = match &select.projection {
        SelectProjection::All => (0..table.columns.len()).collect::<Vec<_>>(),
        SelectProjection::Columns(columns) => columns
            .iter()
            .map(|name| relational_column_index(table, name))
            .collect::<Result<Vec<_>, _>>()?,
        SelectProjection::CountAll => Vec::new(),
        SelectProjection::GroupedCount { column } => vec![relational_column_index(table, column)?],
        SelectProjection::Sum { .. } => Vec::new(),
        SelectProjection::GroupedSum { group_column, .. } => {
            vec![relational_column_index(table, group_column)?]
        }
        SelectProjection::Avg { .. } => Vec::new(),
        SelectProjection::GroupedAvg { group_column, .. } => {
            vec![relational_column_index(table, group_column)?]
        }
        SelectProjection::Min { .. } | SelectProjection::Max { .. } => Vec::new(),
        SelectProjection::GroupedMin { group_column, .. }
        | SelectProjection::GroupedMax { group_column, .. } => {
            vec![relational_column_index(table, group_column)?]
        }
    };
    let mut selected_columns = selected_indexes
        .iter()
        .map(|idx| table.columns[*idx].clone())
        .collect::<Vec<_>>();
    if matches!(
        select.projection,
        SelectProjection::CountAll
            | SelectProjection::GroupedCount { .. }
            | SelectProjection::Sum { .. }
            | SelectProjection::GroupedSum { .. }
            | SelectProjection::Avg { .. }
            | SelectProjection::GroupedAvg { .. }
            | SelectProjection::Min { .. }
            | SelectProjection::GroupedMin { .. }
            | SelectProjection::Max { .. }
            | SelectProjection::GroupedMax { .. }
    ) {
        let aggregate_name = match &select.projection {
            SelectProjection::CountAll | SelectProjection::GroupedCount { .. } => "count",
            SelectProjection::Sum { .. } | SelectProjection::GroupedSum { .. } => "sum",
            SelectProjection::Avg { .. } | SelectProjection::GroupedAvg { .. } => "avg",
            SelectProjection::Min { .. } | SelectProjection::GroupedMin { .. } => "min",
            SelectProjection::Max { .. } | SelectProjection::GroupedMax { .. } => "max",
            SelectProjection::All | SelectProjection::Columns(_) => unreachable!(),
        };
        let (aggregate_ty, aggregate_type_oid, aggregate_type_size) = if matches!(
            select.projection,
            SelectProjection::Avg { .. } | SelectProjection::GroupedAvg { .. }
        ) {
            (SqlType::Int4, 1700, -1)
        } else {
            match aggregate_source_column(table, select)? {
                Some(column) => (column.ty, column.type_oid, column.type_size),
                None => (SqlType::Int4, 20, 8),
            }
        };
        let aggregate_attnum = selected_columns.len() as i16 + 1;
        selected_columns.push(RelationalColumn {
            id: 0,
            table_oid: table.oid,
            attnum: aggregate_attnum,
            name: aggregate_name.to_string(),
            ty: aggregate_ty,
            domain: None,
            default: None,
            type_oid: aggregate_type_oid,
            type_size: aggregate_type_size,
        });
    }
    let raw_filter_groups = if select.filter_groups.is_empty() {
        let filter_refs = if select.filters.is_empty() {
            select.filter.iter().cloned().collect::<Vec<_>>()
        } else {
            select.filters.clone()
        };
        if filter_refs.is_empty() {
            Vec::new()
        } else {
            vec![filter_refs]
        }
    } else {
        select.filter_groups.clone()
    };
    let filter_groups = raw_filter_groups
        .into_iter()
        .map(|group| {
            group
                .into_iter()
                .map(|filter| {
                    relational_column_index(table, &filter.column)
                        .map(|idx| (idx, filter.op, filter.value))
                })
                .collect::<Result<Vec<_>, _>>()
        })
        .collect::<Result<Vec<_>, _>>()?;
    let filters = filter_groups.first().cloned().unwrap_or_default();
    let filter = filters.first().cloned();
    let order = select
        .order_by
        .as_ref()
        .map(|order| {
            if select_is_aggregate_result_column(select, &order.column) {
                Ok((usize::MAX, order.descending))
            } else {
                relational_column_index(table, &order.column).map(|idx| (idx, order.descending))
            }
        })
        .transpose()?;
    if select.distinct {
        match &select.projection {
            SelectProjection::All => {
                return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                    "SELECT DISTINCT * is unsupported".to_string(),
                )));
            }
            SelectProjection::Columns(columns) => {
                if let Some(order) = &select.order_by {
                    if !columns.iter().any(|column| column == &order.column) {
                        return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                            "SELECT DISTINCT ORDER BY must reference a selected column".to_string(),
                        )));
                    }
                }
            }
            SelectProjection::CountAll
            | SelectProjection::GroupedCount { .. }
            | SelectProjection::Sum { .. }
            | SelectProjection::GroupedSum { .. }
            | SelectProjection::Avg { .. }
            | SelectProjection::GroupedAvg { .. }
            | SelectProjection::Min { .. }
            | SelectProjection::GroupedMin { .. }
            | SelectProjection::Max { .. }
            | SelectProjection::GroupedMax { .. } => unreachable!(),
        }
    }
    let group_by_index = if let Some(group_by) = &select.group_by {
        Some(relational_column_index(table, group_by)?)
    } else {
        None
    };
    match (&select.projection, group_by_index) {
        (SelectProjection::CountAll, None) => {}
        (SelectProjection::CountAll, Some(_)) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "GROUP BY requires grouped COUNT(*) projection".to_string(),
            )));
        }
        (SelectProjection::GroupedCount { column }, Some(idx)) => {
            let projected_idx = relational_column_index(table, column)?;
            if projected_idx != idx {
                return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                    "GROUP BY column must match grouped COUNT(*) projection".to_string(),
                )));
            }
            if let Some(order) = &select.order_by {
                if order.column != *column && !order.column.eq_ignore_ascii_case("count") {
                    return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                        "GROUP BY ORDER BY must reference grouped column or count".to_string(),
                    )));
                }
            }
        }
        (SelectProjection::GroupedCount { .. }, None) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "grouped COUNT(*) requires GROUP BY".to_string(),
            )));
        }
        (SelectProjection::Sum { column }, None) => {
            validate_sum_column(table, column)?;
            if let Some(order) = &select.order_by {
                if !order.column.eq_ignore_ascii_case("sum") {
                    return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                        "SUM ORDER BY only supports sum".to_string(),
                    )));
                }
            }
        }
        (SelectProjection::Sum { .. }, Some(_)) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "GROUP BY requires grouped SUM projection".to_string(),
            )));
        }
        (
            SelectProjection::GroupedSum {
                group_column,
                sum_column,
            },
            Some(idx),
        ) => {
            let projected_idx = relational_column_index(table, group_column)?;
            if projected_idx != idx {
                return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                    "GROUP BY column must match grouped SUM projection".to_string(),
                )));
            }
            validate_sum_column(table, sum_column)?;
            if let Some(order) = &select.order_by {
                if order.column != *group_column && !order.column.eq_ignore_ascii_case("sum") {
                    return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                        "GROUP BY ORDER BY must reference grouped column or sum".to_string(),
                    )));
                }
            }
        }
        (SelectProjection::GroupedSum { .. }, None) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "grouped SUM requires GROUP BY".to_string(),
            )));
        }
        (SelectProjection::Avg { column }, None) => {
            validate_avg_column(table, column)?;
            if let Some(order) = &select.order_by {
                if !order.column.eq_ignore_ascii_case("avg") {
                    return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                        "AVG ORDER BY only supports avg".to_string(),
                    )));
                }
            }
        }
        (SelectProjection::Avg { .. }, Some(_)) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "GROUP BY requires grouped AVG projection".to_string(),
            )));
        }
        (
            SelectProjection::GroupedAvg {
                group_column,
                avg_column,
            },
            Some(idx),
        ) => {
            let projected_idx = relational_column_index(table, group_column)?;
            if projected_idx != idx {
                return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                    "GROUP BY column must match grouped AVG projection".to_string(),
                )));
            }
            validate_avg_column(table, avg_column)?;
            if let Some(order) = &select.order_by {
                if order.column != *group_column && !order.column.eq_ignore_ascii_case("avg") {
                    return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                        "GROUP BY ORDER BY must reference grouped column or avg".to_string(),
                    )));
                }
            }
        }
        (SelectProjection::GroupedAvg { .. }, None) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "grouped AVG requires GROUP BY".to_string(),
            )));
        }
        (SelectProjection::Min { column } | SelectProjection::Max { column }, None) => {
            relational_column_index(table, column)?;
            let aggregate_name = if matches!(select.projection, SelectProjection::Min { .. }) {
                "min"
            } else {
                "max"
            };
            if let Some(order) = &select.order_by {
                if !order.column.eq_ignore_ascii_case(aggregate_name) {
                    return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                        "MIN/MAX ORDER BY only supports the aggregate result".to_string(),
                    )));
                }
            }
        }
        (SelectProjection::Min { .. } | SelectProjection::Max { .. }, Some(_)) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "GROUP BY requires grouped MIN/MAX projection".to_string(),
            )));
        }
        (
            SelectProjection::GroupedMin {
                group_column,
                min_column,
            },
            Some(idx),
        ) => {
            validate_grouped_extreme(table, select, group_column, min_column, idx, "min")?;
        }
        (
            SelectProjection::GroupedMax {
                group_column,
                max_column,
            },
            Some(idx),
        ) => {
            validate_grouped_extreme(table, select, group_column, max_column, idx, "max")?;
        }
        (SelectProjection::GroupedMin { .. } | SelectProjection::GroupedMax { .. }, None) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "grouped MIN/MAX requires GROUP BY".to_string(),
            )));
        }
        (SelectProjection::All | SelectProjection::Columns(_), Some(_)) => {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "GROUP BY requires COUNT(*) projection".to_string(),
            )));
        }
        (SelectProjection::All | SelectProjection::Columns(_), None) => {}
    }

    Ok(BoundRelationalSelect {
        selected_columns,
        selected_indexes,
        group_by_index,
        filter,
        filters,
        filter_groups,
        order,
    })
}

type BoundDeleteFilter = (usize, SelectFilterOp, SqlValue);
type BoundDeleteFilterGroup = Vec<BoundDeleteFilter>;
type BoundUpdateAssignment = (usize, SqlValue);

fn bind_delete_filter_groups(
    table: &RelationalTable,
    delete: &Delete,
) -> Result<Vec<BoundDeleteFilterGroup>, ExecuteError> {
    let raw_filter_groups = if delete.filter_groups.is_empty() {
        vec![delete.filters.clone()]
    } else {
        delete.filter_groups.clone()
    };
    if raw_filter_groups.is_empty() || raw_filter_groups.iter().any(Vec::is_empty) {
        return Err(ExecuteError::Engine(EngineError::ApplyFailed(
            "DELETE requires WHERE filters".to_string(),
        )));
    }
    raw_filter_groups
        .into_iter()
        .map(|group| {
            group
                .into_iter()
                .map(|filter| {
                    let idx = relational_column_index(table, &filter.column)?;
                    if !sql_value_matches_type(&filter.value, table.columns[idx].ty) {
                        return Err(ExecuteError::Engine(EngineError::ApplyFailed(format!(
                            "invalid value for column \"{}\"",
                            filter.column
                        ))));
                    }
                    Ok((idx, filter.op, filter.value))
                })
                .collect()
        })
        .collect()
}

fn bind_update_assignments(
    table: &RelationalTable,
    update: &Update,
) -> Result<Vec<BoundUpdateAssignment>, ExecuteError> {
    let mut seen = BTreeSet::new();
    update
        .assignments
        .iter()
        .map(|assignment| {
            let idx = relational_column_index(table, &assignment.column)?;
            if !seen.insert(idx) {
                return Err(ExecuteError::Engine(EngineError::ApplyFailed(format!(
                    "column \"{}\" assigned more than once",
                    assignment.column
                ))));
            }
            if !sql_value_matches_type(&assignment.value, table.columns[idx].ty) {
                return Err(ExecuteError::Engine(EngineError::ApplyFailed(format!(
                    "invalid value for column \"{}\"",
                    assignment.column
                ))));
            }
            Ok((idx, assignment.value.clone()))
        })
        .collect()
}

fn relational_select_pushes_limit(select: &Select) -> bool {
    select.limit.is_some() && select.offset.is_none() && select.order_by.is_none()
}

fn relational_select_pushed_limit(select: &Select, ordered_access_path: bool) -> Option<usize> {
    if select.distinct || select_is_aggregate(select) {
        return None;
    }
    let can_push = select.order_by.is_none() || ordered_access_path;
    if !can_push {
        return None;
    }
    select
        .limit
        .map(|limit| limit.saturating_add(select.offset.unwrap_or(0)))
}

fn relational_select_limit_satisfied_by_access_path(
    select: &Select,
    access_path: &RelationalAccessPath,
) -> bool {
    if select.distinct || select_is_aggregate(select) {
        return false;
    }
    select.offset.is_none()
        && (relational_select_pushes_limit(select)
            || (select.limit.is_some()
                && matches!(access_path, RelationalAccessPath::OrderedKeyBatch { .. })))
}

fn relational_select_needs_host_sql_finalization(
    select: &Select,
    access_path: &RelationalAccessPath,
) -> bool {
    (select_has_relational_filters(select)
        && !matches!(
            access_path,
            RelationalAccessPath::EqualityIndex { .. }
                | RelationalAccessPath::FilteredKeyBatch { .. }
                | RelationalAccessPath::ConjunctiveFilteredKeyBatch { .. }
                | RelationalAccessPath::DisjunctiveFilteredKeyBatch { .. }
                | RelationalAccessPath::OrderedKeyBatch {
                    predicate_column: Some(_),
                    ..
                }
        ))
        || (select.order_by.is_some()
            && !matches!(access_path, RelationalAccessPath::OrderedKeyBatch { .. }))
        || (select.limit.is_some()
            && select.offset.is_none()
            && !select.distinct
            && !relational_select_limit_satisfied_by_access_path(select, access_path))
}

fn select_has_relational_filters(select: &Select) -> bool {
    select.filter.is_some() || !select.filters.is_empty() || !select.filter_groups.is_empty()
}

fn select_is_plain_view_scan(select: &Select) -> bool {
    !select.distinct
        && matches!(select.projection, SelectProjection::All)
        && select.group_by.is_none()
        && select.having_groups.is_empty()
        && !select_has_relational_filters(select)
        && select.order_by.is_none()
        && select.limit.is_none()
        && select.offset.is_none()
}

fn select_is_aggregate(select: &Select) -> bool {
    matches!(
        select.projection,
        SelectProjection::CountAll
            | SelectProjection::GroupedCount { .. }
            | SelectProjection::Sum { .. }
            | SelectProjection::GroupedSum { .. }
            | SelectProjection::Avg { .. }
            | SelectProjection::GroupedAvg { .. }
            | SelectProjection::Min { .. }
            | SelectProjection::GroupedMin { .. }
            | SelectProjection::Max { .. }
            | SelectProjection::GroupedMax { .. }
    )
}

fn select_is_aggregate_result_column(select: &Select, column: &str) -> bool {
    match select.projection {
        SelectProjection::CountAll | SelectProjection::GroupedCount { .. } => {
            column.eq_ignore_ascii_case("count")
        }
        SelectProjection::Sum { .. } | SelectProjection::GroupedSum { .. } => {
            column.eq_ignore_ascii_case("sum")
        }
        SelectProjection::Avg { .. } | SelectProjection::GroupedAvg { .. } => {
            column.eq_ignore_ascii_case("avg")
        }
        SelectProjection::Min { .. } | SelectProjection::GroupedMin { .. } => {
            column.eq_ignore_ascii_case("min")
        }
        SelectProjection::Max { .. } | SelectProjection::GroupedMax { .. } => {
            column.eq_ignore_ascii_case("max")
        }
        SelectProjection::All | SelectProjection::Columns(_) => false,
    }
}

fn select_aggregate_result_column_name(select: &Select) -> Option<&'static str> {
    match select.projection {
        SelectProjection::CountAll | SelectProjection::GroupedCount { .. } => Some("count"),
        SelectProjection::Sum { .. } | SelectProjection::GroupedSum { .. } => Some("sum"),
        SelectProjection::Avg { .. } | SelectProjection::GroupedAvg { .. } => Some("avg"),
        SelectProjection::Min { .. } | SelectProjection::GroupedMin { .. } => Some("min"),
        SelectProjection::Max { .. } | SelectProjection::GroupedMax { .. } => Some("max"),
        SelectProjection::All | SelectProjection::Columns(_) => None,
    }
}

fn grouped_row_matches_having(
    select: &Select,
    group_column: &str,
    group_value: &SqlValue,
    aggregate_name: &'static str,
    aggregate_value: &SqlValue,
) -> Result<bool, ExecuteError> {
    if select.having_groups.is_empty() {
        return Ok(true);
    }

    for filters in &select.having_groups {
        let mut group_matches = true;
        for filter in filters {
            let value = if filter.column == group_column {
                group_value
            } else if filter.column.eq_ignore_ascii_case(aggregate_name) {
                aggregate_value
            } else {
                return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                    "HAVING must reference grouped column or aggregate result".to_string(),
                )));
            };
            if !select_filter_matches(value, filter.op, &filter.value) {
                group_matches = false;
                break;
            }
        }
        if group_matches {
            return Ok(true);
        }
    }

    Ok(false)
}

fn aggregate_source_column<'a>(
    table: &'a RelationalTable,
    select: &Select,
) -> Result<Option<&'a RelationalColumn>, ExecuteError> {
    let column_name = match &select.projection {
        SelectProjection::Min { column } | SelectProjection::Max { column } => Some(column),
        SelectProjection::GroupedMin { min_column, .. } => Some(min_column),
        SelectProjection::GroupedMax { max_column, .. } => Some(max_column),
        SelectProjection::CountAll
        | SelectProjection::GroupedCount { .. }
        | SelectProjection::Sum { .. }
        | SelectProjection::GroupedSum { .. }
        | SelectProjection::Avg { .. }
        | SelectProjection::GroupedAvg { .. }
        | SelectProjection::All
        | SelectProjection::Columns(_) => None,
    };
    let Some(column_name) = column_name else {
        return Ok(None);
    };
    let idx = relational_column_index(table, column_name)?;
    Ok(table.columns.get(idx))
}

fn validate_grouped_extreme(
    table: &RelationalTable,
    select: &Select,
    group_column: &str,
    value_column: &str,
    group_by_idx: usize,
    aggregate_name: &str,
) -> Result<(), ExecuteError> {
    let projected_idx = relational_column_index(table, group_column)?;
    if projected_idx != group_by_idx {
        return Err(ExecuteError::Engine(EngineError::ApplyFailed(
            "GROUP BY column must match grouped MIN/MAX projection".to_string(),
        )));
    }
    relational_column_index(table, value_column)?;
    if let Some(order) = &select.order_by {
        if order.column != group_column && !order.column.eq_ignore_ascii_case(aggregate_name) {
            return Err(ExecuteError::Engine(EngineError::ApplyFailed(
                "GROUP BY ORDER BY must reference grouped column or min/max".to_string(),
            )));
        }
    }
    Ok(())
}

fn validate_sum_column(table: &RelationalTable, column: &str) -> Result<usize, ExecuteError> {
    validate_int4_aggregate_column(table, column, "SUM")
}

fn validate_avg_column(table: &RelationalTable, column: &str) -> Result<usize, ExecuteError> {
    validate_int4_aggregate_column(table, column, "AVG")
}

fn validate_int4_aggregate_column(
    table: &RelationalTable,
    column: &str,
    aggregate: &'static str,
) -> Result<usize, ExecuteError> {
    let idx = relational_column_index(table, column)?;
    if !matches!(table.columns[idx].ty, SqlType::Int4) {
        return Err(ExecuteError::Engine(EngineError::ApplyFailed(
            aggregate_int4_error_message(aggregate).to_string(),
        )));
    }
    Ok(idx)
}

fn aggregate_int4_error_message(aggregate: &str) -> &'static str {
    match aggregate {
        "AVG" => "AVG only supports int4 columns",
        _ => "SUM only supports int4 columns",
    }
}

fn int4_aggregate_value(value: &SqlValue, aggregate: &'static str) -> Result<i32, ExecuteError> {
    match value {
        SqlValue::Int4(value) => Ok(*value),
        SqlValue::Int8(_) | SqlValue::Numeric(_) | SqlValue::Text(_) => Err(ExecuteError::Engine(
            EngineError::ApplyFailed(aggregate_int4_error_message(aggregate).to_string()),
        )),
    }
}

fn average_sql_value(sum: i128, count: usize) -> SqlValue {
    if count == 0 {
        return SqlValue::Numeric(String::new());
    }
    let count = count as i128;
    let negative = sum.is_negative();
    let abs_sum = sum.abs();
    let whole = abs_sum / count;
    let mut remainder = abs_sum % count;
    let mut fractional = String::with_capacity(16);
    for _ in 0..16 {
        remainder *= 10;
        fractional.push(char::from(b'0' + u8::try_from(remainder / count).unwrap()));
        remainder %= count;
    }
    SqlValue::Numeric(format!(
        "{}{}.{fractional}",
        if negative { "-" } else { "" },
        whole
    ))
}

fn current_timestamp_micros() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::ZERO)
        .as_micros()
        .try_into()
        .unwrap_or(u64::MAX)
}

